import numpy as np
from scipy.optimize import curve_fit

def load():
    rows=[]
    for line in open('/app/graphene.dat'):
        p=line.split()
        if len(p)<2: continue
        rows.append((float(p[0].replace(',','.')), float(p[1].replace(',','.'))))
    d=np.array(rows)
    nu=1e7/d[:,0]; y=d[:,1]
    i=np.argsort(nu)
    return nu[i], y[i]

def lor(x,x0,g,a,off):
    return off + a*g**2/((x-x0)**2+g**2)

def lor_lin(x,x0,g,a,off,slope):
    return off + slope*(x-x0) + a*g**2/((x-x0)**2+g**2)

nu,y=load()
windows={'G':[(1400,1750),(1450,1700),(1500,1660),(1470,1700),(1520,1650)],
         '2D':[(2400,2950),(2450,2900),(2500,2850),(2550,2800),(2580,2760)]}
inits={'G':1580.,'2D':2670.}
for name,ws in windows.items():
    print('===',name)
    for (lo,hi) in ws:
        m=(nu>=lo)&(nu<=hi)
        x=nu[m]; yy=y[m]
        off0=np.percentile(yy,20); amp0=yy.max()-off0
        try:
            p,c=curve_fit(lor,x,yy,p0=[inits[name],20.,amp0,off0],maxfev=50000)
            resid=yy-lor(x,*p)
            rms=np.sqrt(np.mean(resid**2))
            print('  const  [%d,%d] n=%3d x0=%9.4f gamma=%8.4f amp=%10.2f off=%10.2f rms=%8.2f' % (lo,hi,m.sum(),p[0],p[1],p[2],p[3],rms))
        except Exception as e:
            print('  const fail',e)
        try:
            p2,_=curve_fit(lor_lin,x,yy,p0=[inits[name],20.,amp0,off0,0.],maxfev=50000)
            rms2=np.sqrt(np.mean((yy-lor_lin(x,*p2))**2))
            print('  linear [%d,%d] n=%3d x0=%9.4f gamma=%8.4f amp=%10.2f off=%10.2f slope=%8.3f rms=%8.2f' % (lo,hi,m.sum(),p2[0],p2[1],p2[2],p2[3],p2[4],rms2))
        except Exception as e:
            print('  lin fail',e)
EOF
